import os,json,base64,hashlib
from pathlib import Path
assert os.uname().nodename=='h100-11'
r=Path('/dataset/shaoshitong/search-r1-rl/bapo-aligned-cohost-node11-v6-20261009')
b=json.loads((r/'scheduler-head/formal-submit-receipt.json').read_text());assert b['job']=='3356' and b['token']=='ef141268a5694dabace114936d380acc'
d=r/'tools/deployment/first5-node11-3356'
assert (r/'tools/deployment').resolve()==r/'tools/deployment'
d.mkdir(exist_ok=True);assert d.resolve()==d and not d.is_symlink()
files={'publish_first5_release.py': {'b64': '', 'sha256': 'a69c85b120f689df6389f3b9a2970d77be92a7017beed74cf67424cad2c4f2bc'}, 'aligned-first5-math-provenance.json': {'b64': '', 'sha256': 'a59a0503e2cbb66448e9ddf3b1ef3bc0e7cf7e0d716b68f273f3cfd664435e13'}, 'aligned_first5_cpu_evidence.py': {'b64': '', 'sha256': '122d951fd04871acad3324f7a3fcee1a53ae48f68af911927504d3802e87b0ad'}, 'aligned_first5_math.py': {'b64': '', 'sha256': '32c037c9e81bb9b0f3c30396f09623db57a3d763754a5d29b3c28e37964e3815'}, 'README.md': {'b64': '', 'sha256': 'aceb6de3870171b89e6373ae65cfcf5ae138d68b3a3a2838300a54b5d821f26e'}, 'FILES.json': {'b64': '', 'sha256': '5adabe922120a77746baa9f8f38ad40abffa764037868f273006716d2d50d384'}}
for name,v in files.items():
 raw=base64.b64decode(v['b64']);assert hashlib.sha256(raw).hexdigest()==v['sha256'];p=d/name
 if p.exists():assert not p.is_symlink() and p.is_file() and p.read_bytes()==raw
 else:
  with p.open('xb') as f:f.write(raw)
 assert hashlib.sha256(p.read_bytes()).hexdigest()==v['sha256']
print(json.dumps({'job':3356,'directory':str(d),'file_sha256':{n:v['sha256'] for n,v in files.items()},'scope':'ISOLATED_HELPERS_ONLY_NO_HF_NO_RELEASE_NO_RUNTIME_CHANGE'}))
